export interface AsamYudaoBridge {
    readonly request?: NonNullable<AsamDataProvider['request']>;
    readonly upload?: NonNullable<AsamDataProvider['upload']>;
    readonly dict?: AsamYudaoDictionaryBridge;
    readonly isErrorNotified?: NonNullable<AsamDataProvider['isErrorNotified']>;
    readonly onError?: NonNullable<AsamDataProvider['onError']>;
}

export interface AsamYudaoDictionaryBridge {
    /**
     * Ensures the host cache is ready. Concurrent readers in one scope/epoch share
     * an operation signal; cancelling one reader does not abort its active peers.
     */
    readonly ensure: (context: AsamRequestContext) => Promise<void>;
    /** Reads a dictionary from the host-owned cache after `ensure` has settled. */
    readonly get: (dictType: string) => readonly AsamDictEntry[];
    /** Invalidates or refreshes the host-owned dictionary cache when it supports that action. */
    readonly refresh?: (context: AsamRequestContext) => Promise<void>;
}
